import { slugify, truncate, wordCount, capitalize } from "../src/strings";

describe("slugify", () => {
  it("lowercases and replaces spaces with hyphens", () => {
    expect(slugify("Hello World")).toBe("hello-world");
  });
  it("removes non-alphanumeric characters", () => {
    expect(slugify("Hello, World!")).toBe("hello-world");
  });
  it("collapses multiple hyphens", () => {
    expect(slugify("foo  bar--baz")).toBe("foo-bar-baz");
  });
  it("trims leading/trailing hyphens", () => {
    expect(slugify("  hello  ")).toBe("hello");
  });
});

describe("truncate", () => {
  it("returns string unchanged when short enough", () => {
    expect(truncate("hello", 10)).toBe("hello");
  });
  it("truncates and appends ellipsis", () => {
    expect(truncate("hello world", 8)).toBe("hello...");
  });
  it("max=3 gives just ellipsis content", () => {
    expect(truncate("hello world", 3)).toBe("...");
  });
});

describe("wordCount", () => {
  it("counts words in normal sentence", () => {
    expect(wordCount("the quick brown fox")).toBe(4);
  });
  it("handles multiple spaces", () => {
    expect(wordCount("  hello   world  ")).toBe(2);
  });
  it("returns 0 for empty string", () => {
    expect(wordCount("")).toBe(0);
  });
});

describe("capitalize", () => {
  it("capitalizes first letter", () => {
    expect(capitalize("hello world")).toBe("Hello world");
  });
  it("handles empty string", () => {
    expect(capitalize("")).toBe("");
  });
  it("leaves already-capitalized unchanged", () => {
    expect(capitalize("Hello")).toBe("Hello");
  });
});
